// font.h - 5x7 bitmap font (romdisk/font.png, generated by tools/make_assets.py). Slice task A6.
// Glyphs are 8x8 cells; advance = 6 px per char at scale 1. Draw at integer scales.
#pragma once
#include "common.h"
namespace bt {
void font_init();
real font_width(const char* s, int scale);
// Top-left anchored. z = 0: automatic draw-order depth (see engine.h).
void font_draw(real x, real y, const char* s, int scale, uint32_t argb, bool shadow = true, float z = 0.0f);
void font_draw_centered(real cx, real y, const char* s, int scale, uint32_t argb, bool shadow = true, float z = 0.0f);
}
